package ch.bbw.zork;/** * Class Command - Part of the "Zork" game. * A command consists of a command word and an optional second word. * * group: Cat team * version: 1.0 * date: October 2026 */public class Command {	private final String commandWord;	private final String secondWord;	/**	 * Creates a command with only one word.	 *	 * @param commandWord the command word or null if the command is unknown	 */	public Command(String commandWord) {		this(commandWord, null);	}	/**	 * Creates a command with two words.	 *	 * @param commandWord the command word or null if the command is unknown	 * @param secondWord  the second word or null	 */	public Command(String commandWord, String secondWord) {		this.commandWord = commandWord;		this.secondWord = secondWord;	}	/** @return the command word or null */	public String getCommandWord() {		return commandWord;	}	/** @return the second word or null */	public String getSecondWord() {		return secondWord;	}	/** @return true if the command word was not understood */	public boolean isUnknown() {		return (commandWord == null);	}	/** @return true if the command has a second word */	public boolean hasSecondWord() {		return (secondWord != null);	}}